import asyncio, os, re, json, subprocess, sys
from playwright.async_api import async_playwright
S = os.environ.get('DECK_TEST_DIR', '/tmp/deck-tests')
DECK = S + '/Test talk/test-talk.html'
PORT = 8821
R = []
ERRS = []
def ok(n, c, x=''):
    R.append(bool(c)); print(('PASS ' if c else 'FAIL ') + n + ('  ' + str(x) if x != '' else '') + ('' if c or not ERRS else '  ERRORS: ' + str(ERRS[-3:])), flush=True)
CENTER = "(sel) => { const e = document.querySelector(sel); const r = e.getBoundingClientRect(); return [r.x + r.width / 2, r.y + r.height / 2]; }"
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        ctx = await b.new_context(viewport={'width': 1440, 'height': 900})
        await ctx.grant_permissions(['clipboard-read', 'clipboard-write'])
        pg = await ctx.new_page()
        errs = ERRS; pg.on('pageerror', lambda e: errs.append(str(e))); pg.on('console', lambda m: errs.append(m.text) if m.type == 'error' else None)
        pg.on('dialog', lambda d: asyncio.ensure_future(d.accept()))
        await pg.goto('http://127.0.0.1:%d/test-talk.html?edit' % PORT); await pg.wait_for_selector('.re-bar'); await pg.wait_for_timeout(1200)
        ev = pg.evaluate
        # --- title slide: type into the placeholders
        t = await ev(CENTER, '.sf [data-ph="title"]')
        await pg.mouse.dblclick(*t); await pg.wait_for_timeout(150)
        await pg.keyboard.type('Arms Control in Orbit'); await pg.keyboard.press('Escape')
        title = await ev("document.querySelector('.sf [data-ph=\"title\"]').innerText.trim()")
        empty = await ev("document.querySelector('.sf [data-ph=\"title\"]').hasAttribute('data-empty')")
        ok('type into the title placeholder', title == 'Arms Control in Orbit' and not empty, (title, empty))
        s = await ev(CENTER, '.sf [data-ph="subtitle"]')
        await pg.mouse.dblclick(*s); await pg.keyboard.type('A. Danagoulian'); await pg.keyboard.press('Enter'); await pg.keyboard.type('MIT'); await pg.keyboard.press('Escape')
        nps = await ev("document.querySelector('.sf [data-ph=\"subtitle\"]').querySelectorAll('.p').length")
        ok('Enter makes a second paragraph', nps == 2, nps)
        await pg.screenshot(path=S + '/shots/t_title.png')
        # --- new slide with the content layout via the menu
        await pg.click('.re-menu-left > .re-btn:has-text("+ Slide")'); await pg.click('.dk-layout:has-text("Title and content")'); await pg.wait_for_timeout(600)
        idx = await ev('Reveal.getIndices()'); lay = await ev("Reveal.getCurrentSlide().getAttribute('data-dk-layout')")
        ok('new content slide after the title', idx['h'] == 1 and lay == 'content' and await ev('Reveal.getTotalSlides()') == 2, (idx, lay))
        nth = await ev("document.querySelectorAll('.dk-thumb').length")
        ok('filmstrip shows two slides', nth == 2, nth)
        t = await ev(CENTER, '.reveal .slides .present [data-ph="title"]')
        await pg.mouse.dblclick(*t); await pg.keyboard.type('Why look at satellites'); await pg.keyboard.press('Escape')
        body = await ev(CENTER, '.reveal .slides .present [data-ph="body"]')
        await pg.mouse.dblclick(*body); await pg.wait_for_timeout(100)
        await pg.keyboard.type('Kosmos 2553 and the 1967 treaty'); await pg.keyboard.press('Enter')
        await pg.keyboard.type('Passive methods'); await pg.keyboard.press('Enter'); await pg.keyboard.press('Tab')
        await pg.keyboard.type('cosmic protons'); await pg.keyboard.press('Enter')
        await pg.keyboard.type('neutrons'); await pg.keyboard.press('Enter'); await pg.keyboard.press('Shift+Tab')
        await pg.keyboard.type('Active interrogation'); await pg.keyboard.press('Escape')
        ps = await ev("[...document.querySelectorAll('.reveal .slides .present [data-ph=\"body\"] .p')].map(p => [p.innerText, p.getAttribute('data-bu'), p.getAttribute('data-lvl')])")
        ok('bulleted list with levels (Tab / Shift-Tab)', len(ps) == 5 and ps[2][2] == '1' and ps[3][2] == '1' and ps[4][2] is None and all(x[1] == 'dot' for x in ps), ps)
        # bullets drawn?
        bw = await ev("getComputedStyle(document.querySelectorAll('.reveal .slides .present [data-ph=\"body\"] .p')[0], '::before').content")
        ok('bullet marker drawn by CSS', '•' in bw or '\\2022' in bw or bw not in ('none', 'normal', ''), bw)
        await pg.screenshot(path=S + '/shots/t_content.png')
        # --- numbered list on the last two paragraphs, then size and bold on a selection
        p4 = await ev("(() => { const p = document.querySelectorAll('.reveal .slides .present [data-ph=\"body\"] .p')[4]; const r = p.getBoundingClientRect(); return [r.x + 40, r.y + r.height / 2]; })()")
        await pg.mouse.dblclick(*p4); await pg.wait_for_timeout(100)
        await pg.click('.re-btn[title="Numbered list"]'); await pg.wait_for_timeout(100)
        bu = await ev("document.querySelectorAll('.reveal .slides .present [data-ph=\"body\"] .p')[4].getAttribute('data-bu')")
        ok('numbered list toggle on the current paragraph', bu == 'num', bu)
        await pg.keyboard.press('Shift+Home'); await pg.keyboard.press('Control+b'); await pg.wait_for_timeout(100)
        bold = await ev("(() => { const p = document.querySelectorAll('.reveal .slides .present [data-ph=\"body\"] .p')[4]; const sp = p.querySelector('span'); return sp && parseInt(getComputedStyle(sp).fontWeight, 10) >= 600 ? p.innerHTML.slice(0, 80) : p.innerHTML.slice(0, 80); })()")
        ok('⌘B while editing bolds the selection', 'font-weight' in bold or '<b>' in bold, bold)
        await pg.click('.dk-size'); await pg.fill('.dk-size', '40'); await pg.keyboard.press('Enter'); await pg.wait_for_timeout(150)
        fs = await ev("(() => { const p = document.querySelectorAll('.reveal .slides .present [data-ph=\"body\"] .p')[4]; return [[...p.querySelectorAll('span')].some(x => getComputedStyle(x).fontSize === '40px') ? '40px' : 'no', document.querySelectorAll('.reveal .slides .present [data-ph=\"body\"] .p').length, getComputedStyle(p).fontSize]; })()")
        await pg.keyboard.press('Escape')
        ok('size field sets the selection to 40px, paragraph keeps its size', fs[0] == '40px' and fs[1] == 5 and fs[2] == '28px', fs)
        # --- selecting the box (not editing) and changing size applies to the whole box
        bx = await ev(CENTER, '.reveal .slides .present [data-ph="body"]')
        await pg.mouse.click(bx[0], bx[1] + 120); await pg.wait_for_timeout(100)
        lab = await pg.inner_text('.re-sel-label')
        await pg.fill('.dk-size', '24'); await pg.keyboard.press('Enter'); await pg.wait_for_timeout(150)
        sizes = await ev("[...document.querySelectorAll('.reveal .slides .present [data-ph=\"body\"] .p')].map(p => getComputedStyle(p).fontSize)")
        ok('size on the selected box applies to every paragraph', all(s_ == '24px' for s_ in sizes), (lab, sizes))
        # --- shapes: rectangle, then an arrow snapped to it; moving the rectangle moves the arrow end
        fr = await ev("(() => { const r = Reveal.getCurrentSlide().querySelector('.sf').getBoundingClientRect(); return [r.x, r.y, r.width / 1280]; })()")
        SS = lambda x, y: (fr[0] + x * fr[2], fr[1] + y * fr[2])
        await pg.click('.re-menu-left > .re-btn:has-text("+ Shape")'); await pg.click('.re-grid .re-btn[title="Rounded rectangle"]')
        await pg.mouse.move(*SS(820, 300)); await pg.mouse.down(); await pg.mouse.move(*SS(1100, 420), steps=6); await pg.mouse.up(); await pg.wait_for_timeout(100)
        rect = await ev("(() => { const e = [...document.querySelectorAll('.reveal .slides .present .shp')].pop(); return [e.dataset.shape, e.dataset.fill, e.getAttribute('data-id')]; })()")
        ok('rounded rectangle drawn with the theme fill', rect[0] == 'roundRect' and rect[1] == '#2e5c8a', rect)
        await pg.click('.re-menu-left > .re-btn:has-text("+ Shape")'); await pg.click('.re-grid .re-btn[title="Arrow"]')
        await pg.mouse.move(*SS(700, 560)); await pg.mouse.down(); await pg.mouse.move(*SS(822, 360), steps=8); await pg.mouse.up(); await pg.wait_for_timeout(100)
        link = await ev("(() => { const e = [...document.querySelectorAll('.reveal .slides .present .shp')].pop(); return [e.dataset.shape, e.getAttribute('data-to'), e.dataset.line]; })()")
        ok('arrow end snapped to the rectangle and remembers it', link[0] == 'line' and link[1] and link[1].endswith('@w'), link)
        end0 = await ev("(() => { const e = [...document.querySelectorAll('.reveal .slides .present .shp')].pop(); const b = e.getBoundingClientRect(); const L = e.dataset.line.split(',').map(Number); return [parseFloat(e.style.left) + L[2], parseFloat(e.style.top) + L[3]]; })()")
        rc = await ev(CENTER, '.reveal .slides .present .shp[data-shape="roundRect"]')
        rb0 = await ev("(() => { const e = document.querySelector('.reveal .slides .present .shp[data-shape=\"roundRect\"]'); return [parseFloat(e.style.left), parseFloat(e.style.top)]; })()")
        await pg.mouse.move(*rc); await pg.mouse.down(); await pg.mouse.move(rc[0] + 60, rc[1] + 40, steps=6); await pg.mouse.up(); await pg.wait_for_timeout(150)
        rb1 = await ev("(() => { const e = document.querySelector('.reveal .slides .present .shp[data-shape=\"roundRect\"]'); return [parseFloat(e.style.left), parseFloat(e.style.top)]; })()")
        end1 = await ev("(() => { const e = [...document.querySelectorAll('.reveal .slides .present .shp[data-shape=\"line\"]')].pop(); const L = e.dataset.line.split(',').map(Number); return [parseFloat(e.style.left) + L[2], parseFloat(e.style.top) + L[3]]; })()")
        dx = end1[0] - end0[0]; dy = end1[1] - end0[1]
        ok('moving the rectangle drags the connected arrow end along', abs(dx - (rb1[0] - rb0[0])) < 0.6 and abs(dy - (rb1[1] - rb0[1])) < 0.6 and abs(dx) > 20, (end0, end1, rb0, rb1))
        srcline = await ev("(() => { return true; })()")
        # --- rotate the rectangle with the handle
        await pg.mouse.click(*(await ev(CENTER, '.reveal .slides .present .shp[data-shape="roundRect"]'))); await pg.wait_for_timeout(100)
        rh = await ev("(() => { const r = document.querySelector('.re-rot').getBoundingClientRect(); return [r.x + r.width / 2, r.y + r.height / 2]; })()")
        c = await ev("(() => { const r = document.querySelector('.re-sel').getBoundingClientRect(); return [r.x + r.width / 2, r.y + r.height / 2]; })()")
        await pg.mouse.move(*rh); await pg.mouse.down(); await pg.mouse.move(c[0] + (c[1] - rh[1]), c[1], steps=8); await pg.mouse.up(); await pg.wait_for_timeout(100)
        rot = await ev("document.querySelector('.reveal .slides .present .shp[data-shape=\"roundRect\"]').style.transform")
        ok('rotation handle rotates (about 90°)', re.search(r'rotate\((8\d|9\d)', rot or '') is not None, rot)
        await pg.fill('.dk-geo input[type=number]:last-of-type', '0')
        await ev("(() => { const i = document.querySelectorAll('.dk-geo input'); const r = i[i.length - 1]; r.value = '0'; r.dispatchEvent(new Event('change')); })()")
        ok('rotation field back to 0 clears the transform', not await ev("document.querySelector('.reveal .slides .present .shp[data-shape=\"roundRect\"]').style.transform"))
        # --- group rectangle + arrow, then ungroup
        await pg.mouse.click(*(await ev(CENTER, '.reveal .slides .present .shp[data-shape="roundRect"]')))
        lp = await ev("(() => { const e = document.querySelector('.reveal .slides .present .shp[data-shape=\"line\"]'); const L = e.dataset.line.split(',').map(Number); const b = e.getBoundingClientRect(); const s = Reveal.getScale(); const fr = Reveal.getCurrentSlide().querySelector('.sf').getBoundingClientRect(); return [fr.x + (parseFloat(e.style.left) + (L[0] + L[2]) / 2) * s, fr.y + (parseFloat(e.style.top) + (L[1] + L[3]) / 2) * s]; })()")
        await pg.keyboard.down('Shift'); await pg.mouse.click(*lp); await pg.keyboard.up('Shift'); await pg.wait_for_timeout(100)
        lab = await pg.inner_text('.re-sel-label')
        await pg.keyboard.press('Control+g'); await pg.wait_for_timeout(150)
        grp = await ev("(() => { const g = document.querySelector('.reveal .slides .present .sf > .e.g'); return g ? [g.children.length, g.getAttribute('data-id')] : null; })()")
        ok('⌘G groups the two', lab.startswith('2 selected') and grp and grp[0] == 2, (lab, grp))
        ok('group is in the source too', await ev("(() => { const n = document.querySelectorAll('.reveal .slides .present .sf > .e.g').length; return n === 1; })()"))
        await pg.keyboard.press('Control+Shift+g'); await pg.wait_for_timeout(150)
        ok('⇧⌘G ungroups, both selected again', not await ev("document.querySelector('.reveal .slides .present .sf > .e.g')") and (await pg.inner_text('.re-sel-label')).startswith('2 selected'))
        await pg.keyboard.press('Escape')
        # --- align: select title box + rectangle, align left
        await pg.screenshot(path=S + '/shots/t_shapes.png')
        # --- builds: body appears on click; builds panel lists it
        await pg.mouse.click(bx[0], bx[1] + 120); await pg.click('.re-menu > .re-btn:has-text("Build")'); await pg.click('.re-menu-list .re-btn:has-text("Appear on click")'); await pg.wait_for_timeout(100)
        # the rectangle disappears on the next click; background picture for every slide via the scope select
        await pg.mouse.click(*(await ev(CENTER, '.reveal .slides .present .shp[data-shape="roundRect"]'))); await pg.click('.re-menu > .re-btn:has-text("Build")'); await pg.click('.re-menu-list .re-btn:has-text("Disappear on click")'); await pg.wait_for_timeout(100)
        fo = await ev("(() => { const e = document.querySelector('.reveal .slides .present .shp[data-shape=\"roundRect\"]'); return [e.classList.contains('fragment'), e.classList.contains('fade-out'), e.getAttribute('data-fragment-index')]; })()")
        ok('Disappear on click: fade-out fragment as step 2', fo == [True, True, '2'], fo)
        await pg.click('.dk-tabs .re-btn:has-text("Builds")'); await pg.wait_for_timeout(100)
        bl = await pg.inner_text('.dk-panel:not([style*="none"])')
        ok('builds panel lists the step', 'Kosmos' in bl or '“' in bl, bl[:120])
        # --- notes
        await pg.fill('.dk-notesbox textarea', 'Mention the 2022 launch.'); await pg.wait_for_timeout(700)
        notes = await ev("(() => { const a = Reveal.getCurrentSlide().querySelector('aside.notes'); return a ? a.textContent : ''; })()")
        ok('notes saved into the slide', 'Mention' in notes, notes)
        # --- picture placeholder on a new "Title and picture" slide: double-click opens the chooser
        await pg.click('.re-menu-left > .re-btn:has-text("+ Slide")'); await pg.click('.dk-layout:has-text("Title and picture")'); await pg.wait_for_timeout(600)
        pc = await ev(CENTER, '.reveal .slides .present [data-ph="picture"]')
        async with pg.expect_file_chooser() as fc:
            await pg.mouse.dblclick(*pc)
        await (await fc.value).set_files(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'testimg.png')); await pg.wait_for_timeout(1200)
        pic = await ev("(() => { const e = document.querySelector('.reveal .slides .present [data-ph=\"picture\"]'); const im = e.querySelector('img'); return [!!im, e.hasAttribute('data-empty'), im && im.naturalWidth > 0, parseFloat(e.style.width), parseFloat(e.style.height)]; })()")
        ok('picture placeholder filled, box fitted to the picture', pic[0] and not pic[1] and pic[2], pic)
        # crop: enter, drag the east handle inwards, picture stays put
        await pg.mouse.click(*(await ev(CENTER, '.reveal .slides .present [data-ph="picture"]')))
        await pg.click('.re-btn:has-text("Crop")'); await pg.wait_for_timeout(100)
        W0 = await ev("(() => { const e = document.querySelector('.reveal .slides .present [data-ph=\"picture\"]'); return [parseFloat(e.style.left), parseFloat(e.style.width)]; })()")
        h = await ev("(() => { const r = document.querySelector('.re-h-e').getBoundingClientRect(); return [r.x + 4, r.y + 4]; })()")
        await pg.mouse.move(*h); await pg.mouse.down(); await pg.mouse.move(h[0] - 120, h[1], steps=6); await pg.mouse.up()
        await pg.keyboard.press('Enter'); await pg.wait_for_timeout(150)
        cr = await ev("(() => { const e = document.querySelector('.reveal .slides .present [data-ph=\"picture\"]'); const im = e.querySelector('img'); return [e.classList.contains('crop'), parseFloat(e.style.width), im.style.width, im.style.left]; })()")
        ok('crop from the right: box narrower, image wider than the box in %', cr[0] and cr[1] < W0[1] - 50 and float(cr[2].rstrip('%')) > 100, (W0, cr))
        await pg.screenshot(path=S + '/shots/t_pic.png')
        # --- hide slide, transition, background colour from the panel
        await pg.click('.dk-tabs .re-btn:has-text("Slide")')
        await pg.evaluate("(() => { const s = [...document.querySelectorAll('.dk-panel select')].find(x => [...x.options].some(o => o.value === 'fade')); s.value = 'fade'; s.dispatchEvent(new Event('change')); })()")
        await pg.wait_for_timeout(300)
        ok('per-slide transition', await ev("Reveal.getCurrentSlide().getAttribute('data-transition')") == 'fade')
        await pg.evaluate("(() => { const s = [...document.querySelectorAll('.dk-panel select')].find(x => [...x.options].some(o => o.value === 'color')); s.value = 'color'; s.dispatchEvent(new Event('change')); })()")
        await pg.wait_for_timeout(300)
        bg = await ev("Reveal.getCurrentSlide().querySelector('.sf').style.background")
        ok('slide background colour set on the frame', bg != '', bg)
        await pg.evaluate("(() => { const s = [...document.querySelectorAll('.dk-panel select')].find(x => [...x.options].some(o => o.value === 'all')); s.value = 'all'; s.dispatchEvent(new Event('change')); })()")
        await pg.wait_for_timeout(600)
        allbg = await ev("(() => { const m = JSON.parse(document.getElementById('deck-meta').textContent); return [m.theme.page, Reveal.getSlides().every(s => !s.querySelector('.sf').style.background)]; })()")
        ok('"Every slide": the background moved into the theme', allbg[0] == '#000000' and allbg[1], allbg)
        # --- settings: light theme + footer + numbers
        await pg.click('.re-menu > .re-btn:has-text("Deck")'); await pg.click('.re-menu-list .re-btn:has-text("Presentation settings")'); await pg.wait_for_timeout(300)
        await pg.select_option('.dk-settings select >> nth=0', 'light')
        await pg.fill('.dk-settings input[type=text]', 'A. Danagoulian · MIT NSE')
        await pg.click('.re-dialog .re-btn:has-text("Apply")'); await pg.wait_for_timeout(800)
        th = await ev("(() => { const m = JSON.parse(document.getElementById('deck-meta').textContent); return [m.theme.name, m.footer, getComputedStyle(Reveal.getCurrentSlide().querySelector('.sf')).color]; })()")
        foot = await ev("[...document.querySelectorAll('.reveal .slides .sf')].filter(f => !f.closest('.dk-tscale')).map(f => !!f.querySelector('[data-master=\"footer\"]')).every(Boolean)")
        nums = await ev("[...document.querySelectorAll('.reveal > .slides > section .sf, .reveal > .slides > section section .sf')].filter(f => !f.closest('.dk-tscale')).map(f => { const n = f.querySelector('[data-slidenum]'); return n ? n.innerText.trim() : null; })")
        ok('light theme applied; footer stamped on every slide; numbers run 1..3', th[0] == 'light' and th[1].startswith('A. Dan') and foot and nums == ['1', '2', '3'], (th, foot, nums))
        await pg.screenshot(path=S + '/shots/t_light.png')
        # --- save and check the file
        await pg.keyboard.press('Control+s'); await pg.wait_for_timeout(1000)
        html = open(DECK).read()
        ok('saved: 3 slides, theme light in file, footer in master template, no editor leftovers',
           html.count('<section') == 3 and '/* theme: light */' in html and '<template id="deck-master">' in html and 'data-master="footer"' in html.split('<body>')[0] and 'contenteditable' not in html and 're-ui' not in html, html.count('<section'))
        # --- reload: everything survives
        await pg.reload(); await pg.wait_for_selector('.re-bar'); await pg.wait_for_timeout(1200)
        ok('reload: slides and settings intact', await ev('Reveal.getTotalSlides()') == 3 and (await ev("JSON.parse(document.getElementById('deck-meta').textContent).footer")).startswith('A. Dan'))
        # --- present: the plain page shows the deck with numbers and no editor
        pv = await ctx.new_page(); pv.on('pageerror', lambda e: errs.append('show ' + str(e)))
        await pv.goto('http://127.0.0.1:%d/test-talk.html?present#/1' % PORT); await pv.wait_for_timeout(1200)
        st = await pv.evaluate("(() => { const o = document.getElementById('deck-start'); return [!!o, Reveal.getIndices().h, document.querySelector('.reveal .slides .present [data-slidenum]').innerText.trim(), getComputedStyle(document.querySelector('.reveal .slides .present [data-ph=\"body\"]')).visibility]; })()")
        ok('present view: start overlay, slide 2, number 2, body (a build) hidden until clicked', st[0] and st[1] == 1 and st[2] == '2', st)
        await pv.screenshot(path=S + '/shots/t_present.png')
        await pv.close()
        ok('no page errors', not errs, errs[:4])
        await b.close()
    print('%d/%d passed' % (sum(R), len(R)))
asyncio.run(main())
